function validateWorldgenKnowledgeBase(r:{schema_version:string;contract_version:string;feature_id:string;boundary:string;raw_data_local:true;aggregate_only:true;effect_receipts:string[];artifact:{content_type:string;content_hash:string;boundary:string}},featureId:string,version:string,contentType:string,digestValues:string[]):void { if(r.schema_version!==RESEARCH_CONTRACT_SCHEMA_VERSION||r.contract_version!==version||r.feature_id!==featureId||r.boundary!==PRECLINICAL_BOUNDARY||r.artifact.boundary!==PRECLINICAL_BOUNDARY||r.artifact.content_type!==contentType||r.raw_data_local!==true||r.aggregate_only!==true||!r.effect_receipts.length||digestValues.some(v=>typeof v!=="string"||!/^[0-9a-f]{64}$/.test(v))||r.artifact.content_hash!==digestValues[digestValues.length-1]) throw new Error("worldgen knowledge receipt identity, boundary, locality, effects, or digests are incomplete"); }
const canonicalKnowledge=(v:string[])=>JSON.stringify([...new Set(v)].sort())===JSON.stringify(v);
