export function validateWorldgenKnowledgeContractReceipt(r:WorldgenKnowledgeContractReceipt):void { validateWorldgenKnowledgeBase(r,r.feature_id,r.contract_version,WORLDGEN_KNOWLEDGE_CONTRACT_CONTENT_TYPE,[r.replay_identity,r.contract_digest]); const fields=new Set(r.field_order),parts=[...r.retained_field_order,...r.missing_field_order,...r.omitted_field_order]; if(!r.field_order.length||fields.size!==r.field_order.length||new Set(parts).size!==fields.size||parts.some(v=>!fields.has(v))) throw new Error("knowledge contract fields do not partition"); for(const v of [r.field_order,r.retained_field_order,r.missing_field_order,r.omitted_field_order,r.semantic_loss_order,r.effect_receipts]) if(!canonicalKnowledge(v)) throw new Error("knowledge contract vectors are not canonical"); }
